// ADDED HERE — this file has no upstream counterpart, and it exists for a MEASURED reason rather
// than a stylistic one.
//
// `FALLBACK_TEARDOWN_DA_GAS_LIMIT` / `FALLBACK_TEARDOWN_L2_GAS_LIMIT` are exported from
// `@aztec/stdlib/gas` at the `ts` anchor `3a68d68ac2`, and the published
// `@aztec/stdlib@5.0.0-nightly.20260626` this package pins against **does not export them** — it
// inlines the same arithmetic inside `GasSettings.fallback()` instead of naming it. Measured, not
// assumed: importing them makes node's ESM loader refuse the module with
//
//   SyntaxError: The requested module '@aztec/stdlib/gas' does not provide an export named
//   'FALLBACK_TEARDOWN_DA_GAS_LIMIT'
//
// and `Object.keys(await import('@aztec/stdlib/gas'))` contains no name matching `FALLBACK` at
// all. `verify_tx_builder_vendored_not_reimplemented` re-derives BOTH halves of that on every run
// — the absence from the installed package AND the presence at the anchor — so the day the nightly
// starts exporting them, this shim is a red assertion rather than dead code nobody notices.
//
// The arithmetic is reproduced verbatim from
//   aztec-packages@3a68d68ac2:yarn-project/stdlib/src/gas/gas_settings.ts:11-16
// so the two values are the anchor's, and the check asserts them against the numbers computed from
// `@aztec/constants` rather than against typed literals.
//
// `spike/src/public/fixtures/gas_compat.ts` is the same shim for the same reason under RI-24, and
// this is deliberately a SECOND copy rather than a cross-package import: `orchestration/` and
// `spike/` are different packages with different dependency postures, and reaching into a spike
// tree from the shipped orchestration would make the spike a runtime dependency of the product.
import { MAX_PROCESSABLE_DA_GAS_PER_CHECKPOINT, MAX_PROCESSABLE_L2_GAS } from '@aztec/constants';

/** Approximate max DA gas limit. Arbitrary, assuming 4 blocks per checkpoint — users should use gas estimation. */
export const APPROXIMATE_MAX_DA_GAS_PER_BLOCK = Math.floor(MAX_PROCESSABLE_DA_GAS_PER_CHECKPOINT / 4);
/** Fallback teardown L2 gas limit. Arbitrary — users should use gas estimation. */
export const FALLBACK_TEARDOWN_L2_GAS_LIMIT = Math.floor(MAX_PROCESSABLE_L2_GAS / 8);
/** Fallback teardown DA gas limit. Arbitrary — users should use gas estimation. */
export const FALLBACK_TEARDOWN_DA_GAS_LIMIT = Math.floor(APPROXIMATE_MAX_DA_GAS_PER_BLOCK / 2);
